<?php

declare(strict_types=1);

namespace Runalyze\Model\Sport;

use Runalyze\Metrics\Velocity\Unit\PaceEnum;
use Runalyze\Parameter\Application\PaceUnit;

/**
 * Generated by hand
 */
final class EntityTest extends \PHPUnit\Framework\TestCase
{
    public function testSimpleObject(): void
    {
        $Sport = new Entity([
            Entity::NAME => 'Sport name',
            Entity::SHORT => 0,
            Entity::CALORIES_PER_HOUR => 700,
            Entity::HR_AVG => 140,
            Entity::HAS_DISTANCES => 1,
            Entity::PACE_UNIT => PaceEnum::METER_PER_SECOND,
            Entity::HAS_POWER => 0,
            Entity::IS_OUTSIDE => 1,
            Entity::DEFAULT_TYPEID => 2,
        ]);

        $this->assertSame('Sport name', $Sport->name());
        $this->assertSame(700, $Sport->caloriesPerHour());
        $this->assertSame(140, $Sport->avgHR());
        $this->assertSame(PaceUnit::M_PER_S, $Sport->getLegacyPaceUnitEnum());
        $this->assertSame(2, $Sport->defaultTypeID());
        $this->assertTrue($Sport->hasDistances());
        $this->assertTrue($Sport->isOutside());

        $this->assertFalse($Sport->usesShortDisplay());
        $this->assertFalse($Sport->hasPower());
    }

    /**
     * @see https://github.com/Runalyze/Runalyze/issues/1585
     */
    public function testPaceUnitForEmptySport(): void
    {
        $Sport = new Entity([]);
        $paceUnit = $Sport->legacyPaceUnit();
        $this->assertInstanceOf(
            \Runalyze\Activity\PaceUnit\KmPerHour::class,
            $paceUnit,
            'legacyPaceUnit() should return a KmPerHour instance for empty sport'
        );
    }
}
